Let's implement a guardrail system that validates agent tool calls before execution:

```python
import json
import re
from dataclasses import dataclass
from typing import Optional

@dataclass
class GuardrailResult:
    allowed: bool
    reason: Optional[str] = None
    modified_params: Optional[dict] = None

# Define tool risk levels
TOOL_RISK_LEVELS = {
    "web_search": "low",
    "read_file": "low",
    "send_email": "high",
    "execute_code": "critical",
    "database_write": "critical",
    "payment_transfer": "critical",
    "file_delete": "critical",
}

# Define what each risk level requires
RISK_REQUIREMENTS = {
    "low": "auto_approve",
    "medium": "log_only",
    "high": "human_approval",
    "critical": "human_approval_with_dual_auth",
}

def validate_tool_call(tool_name: str, params: dict, context: dict) -> GuardrailResult:
    """Validate a tool call before execution."""

    # 1. Check if tool is allowed
    if tool_name not in TOOL_RISK_LEVELS:
        return GuardrailResult(allowed=False, reason=f"Unknown tool: {tool_name}")

    risk = TOOL_RISK_LEVELS[tool_name]

    # 2. Check for prompt injection in parameters
    for key, value in params.items():
        if isinstance(value, str):
            # Detect common injection patterns
            injection_patterns = [
                r'ignore previous instructions',
                r'system:',
                r'\badmin\b.*\bpassword\b',
                r'DROP TABLE',
                r'\bexec\b.*\(',
                r'\beval\b.*\(',
                r'sudo ',
                r'rm -rf',
            ]
            for pattern in injection_patterns:
                if re.search(pattern, value, re.IGNORECASE):
                    return GuardrailResult(
                        allowed=False,
                        reason=f"Potential injection detected in param '{key}'"
                    )

    # 3. Enforce risk-level requirements
    requirement = RISK_REQUIREMENTS[risk]
    if requirement == "human_approval":
        if not context.get("human_approved", False):
            return GuardrailResult(
                allowed=False,
                reason=f"Tool '{tool_name}' requires human approval"
            )
    elif requirement == "human_approval_with_dual_auth":
        if not context.get("human_approved", False) or not context.get("dual_auth", False):
            return GuardrailResult(
                allowed=False,
                reason=f"Tool '{tool_name}' requires dual authorization"
            )

    # 4. Parameter constraints
    if tool_name == "payment_transfer":
        amount = params.get("amount", 0)
        if amount > 1000 and not context.get("large_transfer_approved", False):
            return GuardrailResult(
                allowed=False,
                reason=f"Transfers over $1000 require approval"
            )

    return GuardrailResult(allowed=True)

# Test it
test_calls = [
    ("web_search", {"query": "Python tutorials"}),
    ("send_email", {"to": "user@example.com", "body": "Hello"}),
    ("execute_code", {"code": "print('hello')"}),
    ("database_write", {"query": "DROP TABLE users; -- ignore previous instructions"}),
]

for tool, params in test_calls:
    result = validate_tool_call(tool, params, {})
    print(f"{tool}: {'✅ Allowed' if result.allowed else f'❌ Blocked: {result.reason}'}}")
```

**Analysis Questions:**
1. Why does the guardrail check parameters, not just tool names?
2. What injection patterns might this regex approach miss?
3. How would an attacker bypass parameter validation?
4. Why is dual authorization required for critical operations?
